35	/**
36	 * Mostly used as a facade for all Petclinic controllers
37	 * Also a placeholder for @Transactional and @Cacheable annotations
38	 *
39	 * @author Michael Isvy
40	 * @author Vitaliy Fedoriv
41	 */
42	@Service
43	public class ClinicServiceImpl implements ClinicService {
44	
45	    private final PetRepository petRepository;
46	    private final VetRepository vetRepository;
47	    private final OwnerRepository ownerRepository;
48	    private final VisitRepository visitRepository;
49	    private final SpecialtyRepository specialtyRepository;
50	    private final PetTypeRepository petTypeRepository;
51	    private final CustomerCodeGenerator customerCodeGenerator;
52	    private final MembershipNumberGenerator membershipNumberGenerator;
53	
54	    public ClinicServiceImpl(
55	        PetRepository petRepository,
56	        VetRepository vetRepository,
57	        OwnerRepository ownerRepository,
58	        VisitRepository visitRepository,
59	        SpecialtyRepository specialtyRepository,
60	        PetTypeRepository petTypeRepository,
61	        CustomerCodeGenerator customerCodeGenerator,
62	        MembershipNumberGenerator membershipNumberGenerator) {
63	        this.petRepository = petRepository;
64	        this.vetRepository = vetRepository;
65	        this.ownerRepository = ownerRepository;
66	        this.visitRepository = visitRepository;
67	        this.specialtyRepository = specialtyRepository;
68	        this.petTypeRepository = petTypeRepository;
69	        this.customerCodeGenerator = customerCodeGenerator;
70	        this.membershipNumberGenerator = membershipNumberGenerator;
71	    }
72	
73	    @Override
74	    @Transactional(readOnly = true)
75	    public Collection<Pet> findAllPets() throws DataAccessException {
76	        return petRepository.findAll();
77	    }
78	
79	    @Override
80	    @Transactional(readOnly = true)
81	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
82	        return petRepository.findAll(pageable);
83	    }
84	
85	    @Override
86	    @Transactional
87	    public void deletePet(Pet pet) throws DataAccessException {
88	        petRepository.delete(pet);
89	    }
90	
