24	
25	/**
26	 * Verifies that the required identifying fields of an owner request are present and
27	 * non-blank.
28	 *
29	 * <p>Bean Validation on {@link OwnerFieldsDto} already rejects {@code null} values and
30	 * values failing a field's format, but a purely whitespace value can still slip through
31	 * for free-text fields such as address and city. This validator closes that gap by
32	 * treating any missing or blank value as invalid.
33	 */
34	@Component
35	public class OwnerFieldsValidator {
36	
37	    /**
38	     * <p>An owner supplies an address in either form: the structured {@code addressLine1} or the
39	     * flat {@code address}. It is valid when at least one of them is non-blank; when neither is,
40	     * {@code addressLine1} is reported as missing.
41	     *
42	     * @param fields the submitted owner fields
43	     * @throws MissingOwnerFieldsException if any required field is missing or blank
44	     */
45	    public void validate(OwnerFieldsDto fields) {
46	        List<String> missing = new ArrayList<>();
47	        checkRequired("firstName", fields.getFirstName(), missing);
48	        checkRequired("lastName", fields.getLastName(), missing);
49	        if (isBlank(fields.getAddressLine1()) && isBlank(fields.getAddress())) {
50	            missing.add("addressLine1");
51	        }
52	        checkRequired("city", fields.getCity(), missing);
53	        checkRequired("telephone", fields.getTelephone(), missing);
54	        if (!missing.isEmpty()) {
55	            throw new MissingOwnerFieldsException(missing);
56	        }
57	    }
58	
59	    private boolean isBlank(String value) {
60	        return value == null || value.isBlank();
61	    }
62	
63	    private void checkRequired(String name, String value, List<String> missing) {
64	        if (isBlank(value)) {
65	            missing.add(name);
66	        }
67	    }
68	}
