22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	
39	    @Column(name = "title")
40	    private String title;
41	
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "address_line1")
47	    private String addressLine1;
48	
49	    @Column(name = "address_line2")
50	    private String addressLine2;
51	
52	    @Column(name = "city")
53	    @NotEmpty
54	    private String city;
55	
56	    @Column(name = "telephone")
57	    @NotEmpty
58	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
59	    private String telephone;
60	
61	    @Column(name = "email")
62	    private String email;
63	
64	    @Column(name = "registration_date")
65	    private LocalDate registrationDate;
66	
67	    @Column(name = "birth_date")
68	    private LocalDate birthDate;
69	
70	    @Column(name = "customer_code")
71	    private String customerCode;
72	
73	    @Column(name = "household_id")
74	    private String householdId;
75	
76	    @Column(name = "namesake_count")
77	    private Integer namesakeCount;
78	
79	    @Column(name = "membership_number")
80	    private String membershipNumber;
81	
82	    @Column(name = "bulk_signup_warning")
83	    private Boolean bulkSignupWarning;
84	
85	    @Column(name = "household_size")
86	    private Integer householdSize;
87	
88	    @Column(name = "postcode")
89	    private String postcode;
90	
91	    @Column(name = "possible_duplicate_of")
92	    private Integer possibleDuplicateOf;
93	
94	    @Column(name = "deleted", nullable = false)
95	    private boolean deleted;
96	
97	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
98	    private Set<Pet> pets;
99	
100	    public String getTitle() {
101	        return this.title;
102	    }
103	
104	    public void setTitle(String title) {
105	        this.title = title;
106	    }
107	
108	    public String getAddress() {
109	        return this.address;
110	    }
111	
112	    public void setAddress(String address) {
113	        this.address = address;
114	    }
115	
116	    /**
117	     * The first line of this owner's structured postal address, or {@code null} when the owner was
118	     * created with only the flat {@link #getAddress() address}. Preferred over the flat address when
119	     * present; see {@link #getAddress()} for the composed form.
120	     */
121	    public String getAddressLine1() {
122	        return this.addressLine1;
123	    }
124	
125	    public void setAddressLine1(String addressLine1) {
126	        this.addressLine1 = addressLine1;
127	    }
128	
129	    /**
130	     * The optional second line of this owner's structured postal address, or {@code null} when none
131	     * was supplied. When present it is appended to {@link #getAddressLine1() addressLine1} in the
132	     * composed {@link #getAddress() address}.
133	     */
134	    public String getAddressLine2() {
135	        return this.addressLine2;
136	    }
137	
138	    public void setAddressLine2(String addressLine2) {
139	        this.addressLine2 = addressLine2;
140	    }
141	
142	    public String getCity() {
143	        return this.city;
144	    }
145	
146	    public void setCity(String city) {
147	        this.city = city;
148	    }
149	
150	    public String getTelephone() {
151	        return this.telephone;
152	    }
153	
154	    public void setTelephone(String telephone) {
155	        this.telephone = telephone;
156	    }
157	
158	    /**
159	     * Return this owner's stored E.164 {@link #getTelephone() telephone} formatted for human display
160	     * as the calling code, a space, then the national digits grouped in threes, e.g.
161	     * {@code "+61 412 345 678"}. See {@link TelephoneFormatter}.
162	     */
163	    @Transient
164	    public String getTelephoneDisplay() {
165	        return TelephoneFormatter.toDisplay(this.telephone);
166	    }
167	
168	    public String getEmail() {
169	        return this.email;
170	    }
171	
172	    public void setEmail(String email) {
173	        this.email = email;
174	    }
175	
176	    public LocalDate getRegistrationDate() {
177	        return this.registrationDate;
178	    }
179	
180	    public void setRegistrationDate(LocalDate registrationDate) {
181	        this.registrationDate = registrationDate;
182	    }
183	
184	    /**
185	     * Return this owner's fiscal year, formatted {@code FY<YY>}, derived from the (business-day
186	     * adjusted) {@code registrationDate}. The fiscal year starts on 1 July and is named by the
187	     * calendar year in which it ends. {@code null} when no registration date is known.
188	     */
189	    @Transient
190	    public String getFiscalYear() {
191	        return this.registrationDate == null ? null : FiscalYear.of(this.registrationDate).getLabel();
192	    }
193	
194	    public LocalDate getBirthDate() {
195	        return this.birthDate;
196	    }
197	
198	    public void setBirthDate(LocalDate birthDate) {
199	        this.birthDate = birthDate;
200	    }
201	
202	    public String getCustomerCode() {
203	        return this.customerCode;
204	    }
205	
206	    public void setCustomerCode(String customerCode) {
207	        this.customerCode = customerCode;
208	    }
209	
210	    public String getHouseholdId() {
211	        return this.householdId;
212	    }
213	
214	    public void setHouseholdId(String householdId) {
215	        this.householdId = householdId;
216	    }
217	
218	    public Integer getNamesakeCount() {
219	        return this.namesakeCount;
220	    }
221	
222	    public void setNamesakeCount(Integer namesakeCount) {
223	        this.namesakeCount = namesakeCount;
224	    }
225	
226	    public String getMembershipNumber() {
227	        return this.membershipNumber;
228	    }
229	
230	    public void setMembershipNumber(String membershipNumber) {
231	        this.membershipNumber = membershipNumber;
232	    }
233	
234	    /**
235	     * Whether this owner was created after more than 80 owners had already been registered on the
236	     * same day, flagging an unusually high-volume ("bulk") signup. Captured once at creation.
237	     */
238	    public Boolean getBulkSignupWarning() {
239	        return this.bulkSignupWarning;
240	    }
241	
242	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
243	        this.bulkSignupWarning = bulkSignupWarning;
244	    }
245	
246	    /**
247	     * The number of owners in this owner's household (owners sharing the same {@code householdId},
248	     * counting this owner) captured once at creation.
249	     */
250	    public Integer getHouseholdSize() {
251	        return this.householdSize;
252	    }
253	
254	    public void setHouseholdSize(Integer householdSize) {
255	        this.householdSize = householdSize;
256	    }
257	
258	    /**
259	     * This owner's 4-digit postcode, or {@code null} when none was supplied. When present it is
260	     * validated against the owner's city region at creation (see {@code PostcodeValidator}).
261	     */
262	    public String getPostcode() {
263	        return this.postcode;
264	    }
265	
266	    public void setPostcode(String postcode) {
267	        this.postcode = postcode;
268	    }
269	
270	    /**
271	     * The id of an existing owner this owner was flagged as a possible (soft) duplicate of at
272	     * creation, or {@code null} when none. Because owners sharing a last name and postcode now form
273	     * the same household — rejected as a household duplicate unless declared via {@code sharesHousehold},
274	     * and a declared member is not a suspected duplicate — this is not populated at creation.
275	     * Captured once at creation.
276	     */
277	    public Integer getPossibleDuplicateOf() {
278	        return this.possibleDuplicateOf;
279	    }
280	
281	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
282	        this.possibleDuplicateOf = possibleDuplicateOf;
283	    }
284	
285	    /**
286	     * Whether this owner was flagged as a possible (soft) duplicate of an existing owner at creation,
287	     * i.e. whether {@link #getPossibleDuplicateOf()} is set.
288	     */
289	    @Transient
290	    public Boolean getPossibleDuplicate() {
291	        return this.possibleDuplicateOf != null;
292	    }
293	
294	    /**
295	     * Whether this owner has been soft-deleted. A newly created owner is not deleted; deleting an owner
296	     * flags it {@code true} and retains the record rather than removing it. Duplicate and identity
297	     * checks at creation ignore owners flagged deleted.
298	     */
299	    public boolean isDeleted() {
300	        return this.deleted;
301	    }
302	
303	    public void setDeleted(boolean deleted) {
304	        this.deleted = deleted;
305	    }
306	
307	    /**
308	     * Return this owner's canonical API path, being {@code "/api/owners/"} followed by this owner's
309	     * {@link #getId() id}.
310	     */
311	    @Transient
312	    public String getSelfLink() {
313	        return "/api/owners/" + this.getId();
314	    }
315	
316	    /**
317	     * Return this owner's name formatted for display as {@code "LastName, FirstName"}.
318	     */
319	    @Transient
320	    public String getDisplayName() {
321	        return this.getLastName() + ", " + this.getFirstName();
322	    }
323	
324	    /**
325	     * Return this owner's salutation as the {@link #getTitle() title} and last name separated by a
326	     * space (e.g. {@code "DR Who"}), or just the last name when no title was supplied.
327	     */
328	    @Transient
329	    public String getSalutation() {
330	        return (this.title == null || this.title.isBlank())
331	            ? this.getLastName()
332	            : this.title + " " + this.getLastName();
333	    }
334	
335	    /**
336	     * Return this owner's initials as the upper-cased first letters of the first and last
337	     * name, dot-separated with a trailing dot, e.g. {@code "J.S."}.
338	     */
339	    @Transient
340	    public String getInitials() {
341	        return initial(this.getFirstName()) + initial(this.getLastName());
342	    }
343	
344	    private static String initial(String name) {
345	        return Character.toUpperCase(name.charAt(0)) + ".";
346	    }
347	
348	    /** Points awarded when an email address is present. */
349	    private static final int EMAIL_POINTS = 2;
350	
351	    /** Points awarded when the owner has no namesakes ({@code namesakeCount} is 0). */
352	    private static final int NO_NAMESAKE_POINTS = 1;
353	
354	    /** Points awarded for belonging to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more. */
355	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
356	
357	    /** The household size at or above which {@link #LARGE_HOUSEHOLD_POINTS} are awarded. */
358	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
359	
360	    /** Points awarded for qualifying tenure. */
361	    private static final int TENURE_POINTS = 3;
362	
363	    /** The tenure, in elapsed fiscal years, that must be exceeded to earn {@link #TENURE_POINTS}. */
364	    private static final long MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS = 1;
365	
366	    /**
367	     * Return this owner's membership points, starting at 0: add {@value #EMAIL_POINTS} when an email
368	     * address is present; add {@value #NO_NAMESAKE_POINTS} when the owner has no namesakes
369	     * ({@code namesakeCount} is 0); add {@value #LARGE_HOUSEHOLD_POINTS} for a household of
370	     * {@value #LARGE_HOUSEHOLD_SIZE} or more; add {@value #TENURE_POINTS} for qualifying tenure
371	     * (more than {@value #MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS} elapsed fiscal year since registration).
372	     */
373	    @Transient
374	    public Integer getMembershipPoints() {
375	        int points = 0;
376	        if (hasEmail()) {
377	            points += EMAIL_POINTS;
378	        }
379	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
380	            points += NO_NAMESAKE_POINTS;
381	        }
382	        if (hasLargeHousehold()) {
383	            points += LARGE_HOUSEHOLD_POINTS;
384	        }
385	        if (hasQualifyingTenure()) {
386	            points += TENURE_POINTS;
387	        }
388	        return points;
389	    }
390	
391	    /**
392	     * Return this owner's membership level, derived from {@link #getMembershipPoints() membership
393	     * points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
394	     */
395	    @Transient
396	    public Integer getMembershipLevel() {
397	        int points = getMembershipPoints();
398	        if (points <= 1) {
399	            return 1;
400	        }
401	        if (points <= 3) {
402	            return 2;
403	        }
404	        if (points <= 5) {
405	            return 3;
406	        }
407	        return 4;
408	    }
409	
410	    /**
411	     * Whether this owner belongs to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more, per the
412	     * {@code householdSize} captured at creation. Owners without a recorded household size do not
413	     * qualify.
414	     */
415	    private boolean hasLargeHousehold() {
416	        return this.householdSize != null && this.householdSize >= LARGE_HOUSEHOLD_SIZE;
417	    }
418	
419	    /**
420	     * Whether this owner's tenure exceeds {@value #MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS} elapsed
421	     * fiscal year, i.e. more than that many fiscal years have elapsed between the fiscal year of the
422	     * {@code registrationDate} and the fiscal year of today. Owners without a registration date have
423	     * no measurable tenure and do not qualify.
424	     */
425	    private boolean hasQualifyingTenure() {
426	        if (this.registrationDate == null) {
427	            return false;
428	        }
429	        long elapsedFiscalYears = FiscalYear.of(this.registrationDate).yearsUntil(FiscalYear.of(LocalDate.now()));
430	        return elapsedFiscalYears > MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS;
431	    }
432	
433	    /** Whether this owner has a usable email address (present and not blank). */
434	    private boolean hasEmail() {
435	        return this.email != null && !this.email.isBlank();
436	    }
437	
438	    /**
439	     * Return this owner's preferred contact channel: {@code "EMAIL"} when an email address is
440	     * present, otherwise {@code "PHONE"}.
441	     */
442	    @Transient
443	    public String getContactPreference() {
444	        return hasEmail() ? "EMAIL" : "PHONE";
445	    }
446	
447	    /**
448	     * Return this owner's age band derived from the {@code birthDate} as of the
449	     * {@code registrationDate}, or {@code null} when no birth date is known.
450	     */
451	    @Transient
452	    public AgeBand getAgeBand() {
453	        if (this.birthDate == null || this.registrationDate == null) {
454	            return null;
455	        }
456	        return AgeBand.asOf(this.birthDate, this.registrationDate);
457	    }
458	
459	    /**
460	     * Return this owner's locality: the region segment of the {@code customerCode} (the leading
461	     * {@code <REGION>} of {@code <REGION>-<HASH8>}), which is fixed at creation from the postcode
462	     * (preferred, matched against the known region ranges) falling back to the city-to-region table,
463	     * or {@code "UNKNOWN"} when neither yields a region. Before the customer code is assigned the
464	     * region is resolved directly from the postcode and city.
465	     */
466	    @Transient
467	    public String getLocality() {
468	        if (this.customerCode == null) {
469	            return LocalityResolver.regionFor(this.postcode, this.city);
470	        }
471	        int separator = this.customerCode.indexOf('-');
472	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
473	    }
474	
475	    /**
476	     * Return this owner's timezone: the IANA timezone name for the owner's {@link #getLocality()
477	     * locality} via the fixed region-to-timezone table, or {@code null} when the locality has no
478	     * known timezone.
479	     */
480	    @Transient
481	    public String getTimezone() {
482	        return LocalityResolver.timezoneFor(getLocality());
483	    }
484	
485	    /**
486	     * Return this owner's check digit: the single Luhn check digit computed over the digits of the
487	     * {@code customerCode}.
488	     */
489	    @Transient
490	    public Integer getCheckDigit() {
491	        return this.customerCode == null ? null : LuhnCheckDigit.of(this.customerCode);
492	    }
493	
494	    /**
495	     * Return this owner's identity key, the single derived value all duplicate detection is based
496	     * on: the normalized telephone, email and household id joined with {@code '|'} as
497	     * {@code telephone + "|" + email + "|" + householdId}, with each absent component rendered as
498	     * the empty string. Two owners are duplicates only when their whole identity keys are equal;
499	     * because the telephone is part of the key, members of one household (same {@code householdId})
500	     * with different telephones have distinct keys and are not duplicates.
501	     */
502	    @Transient
503	    public String getIdentityKey() {
504	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
505	    }
506	
507	    private static String keyPart(String value) {
508	        return value == null ? "" : value;
509	    }
510	
511	    protected Set<Pet> getPetsInternal() {
512	        if (this.pets == null) {
513	            this.pets = new HashSet<>();
514	        }
515	        return this.pets;
516	    }
517	
518	    protected void setPetsInternal(Set<Pet> pets) {
519	        this.pets = pets;
520	    }
521	
522	    public List<Pet> getPets() {
523	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
524	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
525	        return Collections.unmodifiableList(sortedPets);
526	    }
527	
528	    public void setPets(List<Pet> pets) {
529	        this.pets = new HashSet<>(pets);
530	    }
531	
532	    public void addPet(Pet pet) {
533	        getPetsInternal().add(pet);
534	        pet.setOwner(this);
535	    }
536	
537	    /**
538	     * Return the Pet with the given name, or null if none found for this Owner.
539	     *
540	     * @param name to test
541	     * @return true if pet name is already in use
542	     */
543	    public Pet getPet(String name) {
544	        return getPet(name, false);
545	    }
546	
547	    /**
548	     * Return the Pet with the given name, or null if none found for this Owner.
549	     *
550	     * @param name to test
551	     * @return true if pet name is already in use
552	     */
553	    public Pet getPet(String name, boolean ignoreNew) {
554	        name = name.toLowerCase();
555	        for (Pet pet : getPetsInternal()) {
556	            if (!ignoreNew || !pet.isNew()) {
557	                String compName = pet.getName();
558	                compName = compName.toLowerCase();
559	                if (compName.equals(name)) {
560	                    return pet;
561	                }
562	            }
563	        }
564	        return null;
565	    }
566	
567	    public Pet getPet(Integer petId) {
568	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
569	    }
570	
571	    @Override
572	    public String toString() {
573	        return new ToStringCreator(this)
574	
575	            .append("id", this.getId())
576	            .append("new", this.isNew())
577	            .append("lastName", this.getLastName())
578	            .append("firstName", this.getFirstName())
579	            .append("address", this.address)
580	            .append("city", this.city)
581	            .append("telephone", this.telephone)
582	            .append("email", this.email)
583	            .append("registrationDate", this.registrationDate)
584	            .toString();
585	    }
586	}
