241	    @Override
242	    @Transactional
243	    public void saveOwner(Owner owner) throws DataAccessException {
244	        if (owner.isNew() && owner.getCustomerCode() == null) {
245	            String region = LocalityResolver.regionFor(owner.getPostcode(), owner.getCity());
246	            String customerCode =
247	                customerCodeGenerator.generate(region, owner.getTelephone(), owner.getLastName());
248	            owner.setCustomerCode(deduplicateCustomerCode(customerCode));
249	        }
250	        if (owner.isNew() && owner.getNamesakeCount() == null) {
251	            owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
252	        }
253	        if (owner.isNew() && owner.getMembershipNumber() == null) {
254	            owner.setMembershipNumber(
255	                membershipNumberGenerator.generate(owner.getCustomerCode(), owner.getRegistrationDate()));
256	        }
257	        if (owner.isNew() && owner.getHouseholdSize() == null) {
258	            owner.setHouseholdSize(countHouseholdMembers(owner));
259	        }
260	        ownerRepository.save(owner);
261	    }
262	
263	    /**
264	     * Count the members of the given (not yet persisted) owner's household: the already stored
265	     * owners sharing its {@code householdId} plus the owner itself. An owner with no household
266	     * ({@code householdId} is null) is a household of one. Used to capture an owner's household
267	     * size at creation time.
268	     */
269	    private int countHouseholdMembers(Owner owner) {
270	        String householdId = owner.getHouseholdId();
271	        if (householdId == null) {
272	            return 1;
273	        }
274	        long existing = ownerRepository.findAll().stream()
275	            .filter(existingOwner -> householdId.equals(existingOwner.getHouseholdId()))
276	            .count();
277	        return (int) (existing + 1);
278	    }
279	
280	    /**
281	     * Count the owners already stored in the given city, compared case-insensitively. Used to
282	     * enforce the per-city capacity limit at creation time.
283	     */
284	    @Override
285	    @Transactional(readOnly = true)
286	    public long countOwnersInCity(String city) throws DataAccessException {
287	        return ownerRepository.findAll().stream()
288	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
289	            .count();
290	    }
291	
292	    /**
293	     * Count the owners already stored whose registration date equals the given date. Used to
294	     * enforce the per-day registration limit at creation time.
295	     */
296	    @Override
297	    @Transactional(readOnly = true)
298	    public long countOwnersRegisteredOn(LocalDate registrationDate) throws DataAccessException {
299	        return ownerRepository.findAll().stream()
300	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
301	            .count();
302	    }
303	
304	    /**
305	     * Count the owners already stored that share the given first and last name, compared
306	     * case-insensitively. Used to capture an owner's namesake count at creation time.
307	     */
308	    private int countNamesakes(String firstName, String lastName) {
309	        return (int) ownerRepository.findAll().stream()
310	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
311	                && equalsIgnoreCase(existing.getLastName(), lastName))
312	            .count();
313	    }
314	
315	    /**
316	     * Ensure the given customer code does not collide with an already stored owner's. When it does,
317	     * append {@code -<n>} using the smallest {@code n} of 2 or more that makes it unique. Used to
