     * Count the owners already stored whose registration date equals the given date. Used to
     * enforce the per-day registration limit at creation time.
     */
    @Override
    @Transactional(readOnly = true)
    public long countOwnersRegisteredOn(LocalDate registrationDate) throws DataAccessException {
        return ownerRepository.findAll().stream()
            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
            .count();
    }

    /**
     * Count the owners already stored that share the given first and last name, compared
     * case-insensitively. Used to capture an owner's namesake count at creation time.
     */
    private int countNamesakes(String firstName, String lastName) {
        return (int) ownerRepository.findAll().stream()
            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
                && equalsIgnoreCase(existing.getLastName(), lastName))
            .count();
    }

    /**
     * Ensure the given customer code does not collide with an already stored owner's. When it does,
     * append {@code -<n>} using the smallest {@code n} of 2 or more that makes it unique. Used to
     * guarantee that distinct owners always receive distinct customer codes at creation time.
     */
    private String deduplicateCustomerCode(String customerCode) {
        Set<String> existing = ownerRepository.findAll().stream()
            .map(Owner::getCustomerCode)
            .filter(code -> code != null)
            .collect(Collectors.toSet());
        if (!existing.contains(customerCode)) {
            return customerCode;
        }
        int suffix = 2;
        while (existing.contains(customerCode + "-" + suffix)) {
            suffix++;
        }
        return customerCode + "-" + suffix;
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return a != null && a.equalsIgnoreCase(b);
    }

    @Override
    @Transactional(readOnly = true)
    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
        return ownerRepository.findByLastName(lastName);
    }

    /**
     * Find the owners already stored whose derived {@link Owner#getIdentityKey() identity key}
     * equals the given key, ignoring any owner flagged {@link Owner#isDeleted() deleted}. Used as
     * the single duplicate-detection check at creation time: a new owner is a duplicate only when
     * its whole identity key matches a non-deleted existing owner's.
     */
    @Override
    @Transactional(readOnly = true)
    public Collection<Owner> findOwnersByIdentityKey(String identityKey) throws DataAccessException {
        return ownerRepository.findAll().stream()
            .filter(owner -> !owner.isDeleted())
            .filter(owner -> owner.getIdentityKey().equals(identityKey))
            .toList();
    }

    /**
     * Find an existing owner belonging to the same household as the given (not-yet-persisted) owner,
     * i.e. one sharing its computed {@link Owner#getHouseholdId() householdId} (derived from last name
     * and postcode). Because the household is keyed on (last name, postcode), such an owner is a
     * household duplicate of the new one. Owners flagged {@link Owner#isDeleted() deleted} are ignored.
     * Returns the first such owner, or {@code null} when the owner has no household
     * ({@code householdId} is null) or no match exists.
     */
    @Override
    @Transactional(readOnly = true)
    public Owner findHouseholdDuplicateOf(Owner owner) throws DataAccessException {
        String householdId = owner.getHouseholdId();
        if (householdId == null) {
            return null;
        }
        return ownerRepository.findAll().stream()
            .filter(existing -> !existing.isDeleted())
            .filter(existing -> householdId.equals(existing.getHouseholdId()))
            .findFirst()
            .orElse(null);
    }

    @Override
    @Transactional(readOnly = true)
    public Collection<Visit> findVisitsByPetId(int petId) {
        return visitRepository.findByPetId(petId);
    }

    @Override
    @Transactional(readOnly = true)
    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
    }

    private <T> T findEntityById(Supplier<T> supplier) {
        try {
            return supplier.get();
        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
            // Just ignore not found exceptions for Jdbc/Jpa realization
            return null;
        }
    }

}

